CREATE TABLE IF NOT EXISTS "aigc_task" (
    "id" bigint NOT NULL GENERATED BY DEFAULT AS IDENTITY,
    "task_no" varchar(64) NOT NULL,
    "client_request_id" varchar(128),
    "user_id" bigint NOT NULL,
    "task_type" varchar(64) NOT NULL,
    "capability" varchar(64) NOT NULL,
    "model_id" bigint NOT NULL,
    "provider_id" bigint,
    "status" varchar(32) NOT NULL,
    "progress" int DEFAULT 0,
    "estimated_duration_millis" bigint,
    "request_params" varchar(4096),
    "price_snapshot" varchar(4096),
    "freeze_id" bigint,
    "sale_price" decimal(18,6),
    "cost_price" decimal(18,6),
    "currency_type" varchar(32),
    "external_task_id" varchar(128),
    "output_asset_id" bigint,
    "output_asset_type" varchar(32),
    "output_summary" varchar(1024),
    "fail_code" varchar(128),
    "fail_reason" varchar(1024),
    "submit_time" datetime,
    "start_time" datetime,
    "callback_time" datetime,
    "finish_time" datetime,
    "expire_time" datetime,
    "retry_count" int DEFAULT 0,
    "max_retry_count" int DEFAULT 3,
    "remark" varchar(512),
    "creator" varchar(64) DEFAULT '',
    "create_time" datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "updater" varchar(64) DEFAULT '',
    "update_time" datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "deleted" bit NOT NULL DEFAULT FALSE,
    "tenant_id" bigint NOT NULL DEFAULT 0,
    PRIMARY KEY ("id"),
    CONSTRAINT "uk_task_no" UNIQUE ("task_no"),
    CONSTRAINT "uk_client_request" UNIQUE ("tenant_id", "user_id", "client_request_id")
);

CREATE TABLE IF NOT EXISTS "aigc_task_result" (
    "id" bigint NOT NULL GENERATED BY DEFAULT AS IDENTITY,
    "task_id" bigint NOT NULL,
    "output_text" clob,
    "output_data" varchar(4096),
    "creator" varchar(64) DEFAULT '',
    "create_time" datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "updater" varchar(64) DEFAULT '',
    "update_time" datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "deleted" bit NOT NULL DEFAULT FALSE,
    "tenant_id" bigint NOT NULL DEFAULT 0,
    PRIMARY KEY ("id"),
    CONSTRAINT "uk_task_result_task_id" UNIQUE ("task_id")
);

CREATE TABLE IF NOT EXISTS "aigc_task_log" (
    "id" bigint NOT NULL GENERATED BY DEFAULT AS IDENTITY,
    "task_id" bigint NOT NULL,
    "task_no" varchar(64),
    "from_status" varchar(32),
    "to_status" varchar(32),
    "action" varchar(64) NOT NULL,
    "message" varchar(1024),
    "operator_type" varchar(32),
    "operator_id" bigint,
    "extra_info" varchar(4096),
    "creator" varchar(64) DEFAULT '',
    "create_time" datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "updater" varchar(64) DEFAULT '',
    "update_time" datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "deleted" bit NOT NULL DEFAULT FALSE,
    "tenant_id" bigint NOT NULL DEFAULT 0,
    PRIMARY KEY ("id")
);

CREATE TABLE IF NOT EXISTS "aigc_task_callback" (
    "id" bigint NOT NULL GENERATED BY DEFAULT AS IDENTITY,
    "callback_no" varchar(64) NOT NULL,
    "task_id" bigint,
    "task_no" varchar(64),
    "provider_id" bigint,
    "provider_code" varchar(64) NOT NULL,
    "external_task_id" varchar(128) NOT NULL,
    "callback_type" varchar(64) NOT NULL,
    "callback_status" varchar(32) NOT NULL,
    "raw_body" clob,
    "headers" varchar(4096),
    "signature" varchar(512),
    "process_result" varchar(4096),
    "fail_reason" varchar(1024),
    "received_time" datetime,
    "processed_time" datetime,
    "creator" varchar(64) DEFAULT '',
    "create_time" datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "updater" varchar(64) DEFAULT '',
    "update_time" datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "deleted" bit NOT NULL DEFAULT FALSE,
    "tenant_id" bigint NOT NULL DEFAULT 0,
    PRIMARY KEY ("id"),
    CONSTRAINT "uk_external_callback" UNIQUE ("provider_code", "external_task_id", "callback_type")
);

CREATE TABLE IF NOT EXISTS "aigc_task_retry" (
    "id" bigint NOT NULL GENERATED BY DEFAULT AS IDENTITY,
    "retry_no" varchar(64) NOT NULL,
    "task_id" bigint NOT NULL,
    "task_no" varchar(64),
    "retry_type" varchar(32),
    "retry_status" varchar(32) NOT NULL,
    "retry_count" int DEFAULT 1,
    "next_retry_time" datetime,
    "start_time" datetime,
    "finish_time" datetime,
    "fail_reason" varchar(1024),
    "operator_id" bigint,
    "creator" varchar(64) DEFAULT '',
    "create_time" datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "updater" varchar(64) DEFAULT '',
    "update_time" datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "deleted" bit NOT NULL DEFAULT FALSE,
    "tenant_id" bigint NOT NULL DEFAULT 0,
    PRIMARY KEY ("id"),
    CONSTRAINT "uk_retry_no" UNIQUE ("retry_no")
);
